import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    # Normalize turn angle around 180° (smooth U-turn for adjacent swaths)
    turn_penalty = np.abs(turn_deg - 180.0) + 1e-3

    # Dynamic strategy: when battery is low (<60%), prioritize returning to depot; otherwise prioritize smooth flight
    if energy_left_frac < 0.6 and fits:
        dist_reward = 1.0 / (depot_dist_m + 1e-3) * (1.0 - turn_penalty/360.0)
    else:
        dist_reward = 1.0 / (dist_m + 1e-3) * (1.0 - turn_penalty/360.0)

    # Apply strict fit constraint multiplicatively to prevent invalid routes from being selected with high priority
    return np.where(fits, dist_reward * (swath_len_m + 1e-3), 1e-9)

